<template>
  <div class="comment-management">
    <h2>卫星地面融合网络社区-评论管理</h2>

    <!-- 评论列表 -->
    <el-card>
      <el-table :data="comments" style="width: 100%" v-loading="loading">
        <el-table-column prop="id" label="ID" width="60"></el-table-column>
        <el-table-column prop="content" label="评论内容" show-overflow-tooltip>
          <template slot-scope="scope">
            <span class="comment-content">{{ scope.row.content }}</span>
          </template>
        </el-table-column>
        <el-table-column prop="author" label="评论者" width="100">
          <template slot-scope="scope">
            {{ scope.row.author ? scope.row.author.nickname : '-' }}
          </template>
        </el-table-column>
        <el-table-column prop="level" label="级别" width="80">
          <template slot-scope="scope">
            <el-tag :type="scope.row.level === '1' ? 'primary' : 'success'" size="small">
              {{ scope.row.level === '1' ? '一级' : '二级' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="createDate" label="发布时间" width="160">
          <template slot-scope="scope">
            {{ formatDate(scope.row.createDate) }}
          </template>
        </el-table-column>
        <el-table-column label="操作" width="150" fixed="right">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="viewArticle(scope.row)">查看文章</el-button>
            <el-button type="text" size="small" class="danger-text" @click="deleteComment(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页 -->
      <el-pagination
        @current-change="handlePageChange"
        :current-page="pagination.pageNumber"
        :page-size="pagination.pageSize"
        :total="pagination.total"
        layout="total, prev, pager, next"
        style="margin-top: 20px; text-align: right;"
      ></el-pagination>
    </el-card>
  </div>
</template>

<script>
import { getComments, deleteComment as deleteCommentApi } from '@/api/comment'

export default {
  name: 'CommentManagement',
  data() {
    return {
      comments: [],
      loading: false,
      pagination: {
        pageNumber: 1,
        pageSize: 10,
        total: 0
      }
    }
  },
  created() {
    this.loadComments()
  },
  methods: {
    async loadComments() {
      this.loading = true
      try {
        const res = await getComments({}, {
          pageNumber: this.pagination.pageNumber,
          pageSize: this.pagination.pageSize
        })
        this.comments = res.data || []
        this.pagination.total = res.data ? res.data.length : 0
      } catch (error) {
        this.$message.error('加载评论列表失败')
      } finally {
        this.loading = false
      }
    },
    handlePageChange(page) {
      this.pagination.pageNumber = page
      this.loadComments()
    },
    viewArticle(comment) {
      if (comment.article) {
        this.$router.push(`/view/${comment.article.id}`)
      }
    },
    async deleteComment(comment) {
      try {
        await this.$confirm('确定要删除这条评论吗？此操作不可恢复。', '警告', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })

        await deleteCommentApi(comment.id)
        this.$message.success('删除成功')
        this.loadComments()
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error('删除失败')
        }
      }
    },
    formatDate(date) {
      if (!date) return '-'
      return date.substring(0, 19).replace('T', ' ')
    }
  }
}
</script>

<style scoped>
.comment-management {
  padding: 20px;
}

.comment-management h2 {
  margin-bottom: 20px;
  font-size: 24px;
  color: #303133;
}

.comment-content {
  max-width: 300px;
  display: inline-block;
}

.danger-text {
  color: #F56C6C;
}

.danger-text:hover {
  color: #f66;
}

/* 手机端适配 */
@media screen and (max-width: 767px) {
  .comment-management {
    padding: 10px;
  }

  .comment-management h2 {
    font-size: 18px;
    margin-bottom: 15px;
  }

  .comment-content {
    max-width: 150px;
  }

  .el-table {
    font-size: 12px;
  }

  .el-table .cell {
    padding: 8px 4px;
  }
}

/* 平板端适配 */
@media screen and (min-width: 768px) and (max-width: 1024px) {
  .comment-management {
    padding: 15px;
  }

  .comment-management h2 {
    font-size: 20px;
  }

  .comment-content {
    max-width: 200px;
  }

  .el-table {
    font-size: 13px;
  }
}
</style>



